s=s[:start]+'''.calculation-workbench .compact-macro-form{display:grid;gap:24px;padding:0;background:none;border:0;border-radius:0}.compact-macro-form .macro-details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin:0}.compact-macro-form .field{margin:0;min-width:0}.compact-macro-form .field>label,.field-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:40px;margin:0 0 8px;font-size:.87rem;font-weight:600}.field-heading label{margin:0}.field-heading .units-toggle{margin:0;flex-wrap:nowrap;gap:4px}.compact-macro-form input,.compact-macro-form select{margin-top:0}.height-pair{flex-wrap:nowrap}.height-pair label{position:relative;margin:0}.height-pair input{padding-right:32px}.input-unit{position:absolute;right:12px;top:12px;color:var(--muted);font-size:.85rem;pointer-events:none}.macro-explanations{display:grid;grid-template-columns:1fr 1fr;gap:24px}.macro-explanations details{margin:0}.compact-macro-form .publication-calculator-note{margin:0;max-width:none}.results.empty:empty{display:none}.compact-macro-form>.calc-submit{justify-self:start;min-width:240px}
'''+s[end:]
swap('.calculation-workbench{width:min(1100px,calc(100% - 96px));margin:40px auto;display:block}', '.calculation-workbench{width:min(1100px,100%);margin:0 auto;display:block}')
