swap('.market-search-head .search-box{padding:20px;margin-top:25px}', '.market-search-head .search-box{padding:0;margin-top:24px}')
# Delete superseded fieldset positioning and duplicate shortcut styling.
s=re.sub(r'\.compact-macro-form>fieldset[^{}]*\{[^{}]*\}','',s)
s=s.replace('.calculation-workbench .compact-macro-form{grid-template-columns:1fr 1fr}', '.compact-macro-form .macro-details{grid-template-columns:1fr 1fr}')
s=s.replace('.calculation-workbench .compact-macro-form{grid-template-columns:1fr}', '.compact-macro-form .macro-details,.macro-explanations{grid-template-columns:1fr}.compact-macro-form>.calc-submit{width:100%;min-width:0}')
s=re.sub(r'\.brand-caption\{[^}]*\}|\.back-to-top\{[^}]*\}|\.restaurant-initial\{[^}]*\}', '',s)
s=s.replace('margin-bottom:30px','margin-bottom:32px').replace('gap:30px','gap:32px').replace('gap:35px','gap:32px').replace('gap:65px','gap:64px')
p.write_text(s,encoding='utf-8')

p=R/'tools/market-content.css';s=p.read_text(encoding='utf-8')
s=s.replace('.submission-sources,.source-box,.sources-box{background:var(--soft);padding:24px;border-radius:0;border-left:3px solid var(--green);', '.submission-sources,.source-box,.sources-box{padding:24px 0;border-top:1px solid var(--line);')
