s=s.replace('.single-macro-card{padding:22px 0;border-top:1px solid var(--line)}', '.single-macro-card{display:grid;grid-template-rows:subgrid;grid-row:span 3;row-gap:0;padding:24px 0;border-top:1px solid var(--line)}.single-macro-form{display:flex;flex-direction:column;gap:16px}.single-macro-form .field{margin:0}.single-macro-form .field>label{display:flex;align-items:center;min-height:40px;margin:0 0 8px}.single-macro-form input,.single-macro-form select{margin-top:0}.single-macro-form>.calc-submit{margin-top:auto;width:100%}.single-macro-form .field-heading{margin-bottom:8px}')
s=s.replace('.single-card-head{display:flex;gap:12px;margin-bottom:16px}', '.single-card-head{display:flex;gap:12px;margin-bottom:16px}.single-card-head h3{margin:0}')
s=s.replace('.single-macro-result{margin-top:18px;padding:16px;background:var(--soft);border-radius:var(--radius)}', '.single-macro-result{margin-top:16px;padding:16px 0;border-top:1px solid var(--line)}')
s=s.replace('.comparison-basis{padding:14px;background:var(--surface);margin-bottom:18px}', '.comparison-basis{margin-bottom:24px}')
s=s.replace('.clear-tool-card{display:flex;gap:18px;align-items:center;', '.clear-tool-card{display:flex;gap:16px;align-items:start;')
s=s.replace('.clear-tool-card h3{margin-bottom:5px}', '.clear-tool-card h3{margin-bottom:8px}.clear-tool-card:after{content:"→";margin-left:auto;align-self:center;color:var(--green)}.clear-tool-card:hover h3{text-decoration:underline;text-underline-offset:4px}')
s=s.replace('.chain-card{padding:25px 0;', '.chain-card{padding:24px 0;')
s=s.replace('grid-template-columns:44px minmax(0,1fr);gap:4px 15px;', 'grid-template-columns:48px minmax(0,1fr);gap:4px 16px;')
s=s.replace('.directory-logo{width:42px;height:42px;margin-bottom:14px}', '.directory-logo{width:48px;height:48px;margin:0;flex-shrink:0}')
s=s.replace('.contact-address{padding:25px;background:var(--surface);border-radius:var(--radius);margin-top:24px}', '.contact-address{padding:0;margin-top:24px}')
s=s.replace('.clear-about-source{background:var(--soft)}','')
s=re.sub(r'\.back-to-top[^{}]*\{[^{}]*\}|\.restaurant-initial\{[^}]*\}', '',s)
s=s.replace('.publication-example,.practical-example{padding:20px}', '.publication-example,.practical-example{padding:24px 0}')
s=s.replace('.contact-address{padding:21px}', '')
s=s.replace('.single-macro-grid{grid-template-columns:1fr;gap:10px}', '.single-macro-grid{grid-template-columns:1fr;gap:24px}.single-macro-card{display:block;grid-row:auto}.single-card-head{margin-bottom:16px}.example-grid>*+*,.advice-grid>*+*{border-left:0;border-top:1px solid var(--line);padding:16px 0 0}')
s=s.replace('@media(max-width:640px){}','').replace('@media(max-width:1050px){}','')
# Keep only the owning focused metric rules and one no-script nav definition.
s=re.sub(r'\.focused-metrics\{display:grid;grid-template-columns:repeat\(2,minmax\(0,1fr\)\);gap:18px\}', '',s)
s=re.sub(r'\.focused-metric\{padding:14px;background:var\(--surface\);border-radius:var\(--radius\)\}', '',s)
s=re.sub(r'\.no-script-nav\{[^}]*\}', '',s)
p.write_text(s,encoding='utf-8')
print('Owning Market layout rules replaced')
